from requests import Request
import io

class Wrapper:
    def __init__(self, fileobj):
        self._fileobj = fileobj
    def __getattr__(self, name):
        return getattr(self._fileobj, name)

def test_encode_files():
    f = io.BytesIO(b"hello world")
    w = Wrapper(f)

    # We need a Request object to call _encode_files.
    req = Request('POST', 'http://example.com', files={'file': w})

    try:
        # _encode_files is a method of Request (via RequestEncodingMixin)
        body, content_type = req._encode_files({'file': w}, None)
        print("Successfully encoded files")
        print(f"Body: {body}")
    except Exception as e:
        print(f"Failed to encode files: {e}")
        import traceback
        traceback.print_exc()

if __name__ == "__main__":
    test_encode_files()
